-- ============================================================================
-- find_confusable_law_pairs.sql
-- Q1(10ㆍ27법난 vs 다른 특별법) 처럼 "제1조(목적)" 등 도입부 조문이 서로 비슷해서
-- 벡터 검색이 헷갈릴 만한 법령 쌍을 자동으로 찾습니다.
-- 여기서 나온 쌍으로 평가셋(eval_dataset.json)에 문항을 추가하면,
-- 이번 title 포함 재임베딩 효과가 다른 케이스에도 일반화되는지 체계적으로 검증할 수 있습니다.
-- ============================================================================

-- [1] 제1조(목적) 조항끼리, 서로 다른 법인데 본문(content)이 트라이그램 기준 유사한 쌍
--     content만 비교합니다 (title 아님) - "임베딩에서 title 빠지면 헷갈릴 소지가 큰" 원래
--     문제 상황을 그대로 재현하기 위함입니다.
SELECT
    a.chunk_id AS chunk_a,
    a.title    AS title_a,
    b.chunk_id AS chunk_b,
    b.title    AS title_b,
    similarity(a.content, b.content) AS content_similarity
FROM legal_chunks a
JOIN legal_chunks b
  ON a.doc_type = 'law'
 AND b.doc_type = 'law'
 AND a.doc_id < b.doc_id                 -- 같은 쌍 중복 제거, 자기 자신 제외
 AND a.chunk_id LIKE '%\_art\_0001001'   -- 제1조(주로 목적/정의) 조항만
 AND b.chunk_id LIKE '%\_art\_0001001'
WHERE similarity(a.content, b.content) > 0.45
ORDER BY content_similarity DESC
LIMIT 40;

