-- [2] 위와 동일하되 "정의" 조항(보통 제2조)까지 포함해서 넓게 탐색
SELECT
    a.chunk_id AS chunk_a,
    a.title    AS title_a,
    b.chunk_id AS chunk_b,
    b.title    AS title_b,
    similarity(a.content, b.content) AS content_similarity
FROM legal_chunks a
JOIN legal_chunks b
  ON a.doc_type = 'law'
 AND b.doc_type = 'law'
 AND a.doc_id < b.doc_id
 AND (a.chunk_id LIKE '%\_art\_0001001' OR a.chunk_id LIKE '%\_art\_0002001')
 AND (b.chunk_id LIKE '%\_art\_0001001' OR b.chunk_id LIKE '%\_art\_0002001')
WHERE similarity(a.content, b.content) > 0.4
ORDER BY content_similarity DESC
LIMIT 60;

