-- [3] doc_type별 청크 수 분포 재확인 (평가셋을 doc_type 비율에 맞게 배분할 때 참고용)
--     실제 데이터 비중과 완전히 비례시킬 필요는 없지만, 통계적으로 말이 되려면
--     doc_type당 최소 8~10문항은 확보하는 걸 권장합니다.
SELECT doc_type, COUNT(*) AS total_chunks,
       ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 1) AS pct
FROM legal_chunks
GROUP BY doc_type
ORDER BY total_chunks DESC;